package com.platformpoc;

import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import java.util.Map;

// inventory-api - generated by the Platform POC Quarkus golden path.
// Health checks come for free from quarkus-smallrye-health: /q/health/live, /q/health/ready
@Path("/")
public class ServiceResource {

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Map<String, String> hello() {
        return Map.of("service", "inventory-api", "message", "Hello from the Quarkus golden path");
    }
}
